/* Shared contact drawer: configurable transport, copy on PC and dial on Android. */
(()=>{'use strict';const fields=[['name','Nom'],['phone','Téléphone'],['email','E-mail'],['address','Adresse'],['website','Site internet'],['doctolib','Doctolib'],['notes','Notes']];
const N=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e},B=(text,fn)=>{const b=N('button','',text);b.type='button';b.onclick=fn;return b};
const glyph=()=>{const s=document.createElementNS('http://www.w3.org/2000/svg','svg');s.setAttribute('viewBox','0 0 24 24');s.setAttribute('fill','none');s.setAttribute('stroke','currentColor');s.setAttribute('stroke-width','1.7');s.setAttribute('aria-hidden','true');s.innerHTML='<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>';return s};
window.AtelierContacts={button(owner,config){const b=B('',e=>{e.preventDefault();e.stopPropagation();window.AtelierContacts.open(owner,config)});b.className='admin-people-button';b.title='Contacts';b.setAttribute('aria-label','Contacts de '+owner.title);b.append(glyph());return b},open(owner,config){document.getElementById('adminContactDrawer')?.remove();const drawer=N('aside','admin-contact-drawer');drawer.id='adminContactDrawer';drawer.setAttribute('role','dialog');drawer.setAttribute('aria-modal','false');drawer.setAttribute('aria-label','Contacts de '+owner.title);const bar=N('div','admin-contact-bar');bar.append(N('strong','','Contacts'),B('×',()=>drawer.remove()));bar.lastChild.setAttribute('aria-label','Fermer les contacts');const search=N('input');search.type='search';search.placeholder='Nom, organisme, e-mail…';search.setAttribute('aria-label','Rechercher un contact');const list=N('div','admin-contact-list'),status=N('p','muted');status.setAttribute('role','status');drawer.append(bar,search,list,status);document.body.append(drawer);drawer.onkeydown=e=>{if(e.key==='Escape')drawer.remove()};
let directory=false;const save=async(path,body)=>{try{await config.command(path,body);await config.refresh();draw()}catch(e){status.textContent=e.message}};
function editor(contact=null){const operation_id=crypto.randomUUID();list.replaceChildren();const form=N('form','admin-contact-form'),inputs={};for(const [key,label]of fields){const l=N('label','',label),input=N(key==='notes'?'textarea':'input');input.name=key;input.value=contact?.[key]||'';if(input.tagName==='INPUT')input.type=key==='phone'?'tel':key==='email'?'email':'text';input.maxLength=key==='name'?120:2000;input.required=key==='name';l.append(input);form.append(l);inputs[key]=input}const submit=B('Enregistrer',()=>{});submit.type='submit';form.append(submit,B('Annuler',draw));form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{await config.command('/contact',{...Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,v.value])),admin_id:owner.id,contact_id:contact?.id,revision:contact?.revision,operation_id});await config.refresh();draw()}catch(err){status.textContent=err.message}finally{submit.disabled=false}};list.append(form);inputs.name.focus()}
function external(label,url,icon=false){const a=N('a','admin-contact-link',label);a.href=url;if(!url.startsWith('tel:')&&!url.startsWith('mailto:')){a.target='_blank';a.rel='noopener noreferrer'}return a}
function draw(){if(!drawer.isConnected)return;list.replaceChildren();status.textContent=config.pending?.()?'Modification(s) conservée(s) sur ce téléphone, en attente du PC.':'';const data=config.data(),linked=new Set(data.contact_links?.[String(owner.id)]||[]),q=search.value.toLocaleLowerCase('fr');list.append(B('+ Contact',()=>editor()),B(directory?'Contacts liés':'Relier un contact existant',()=>{directory=!directory;draw()}));const matches=(data.contact_book||[]).filter(c=>(linked.has(c.id)||directory||q)&&fields.some(([k])=>String(c[k]||'').toLocaleLowerCase('fr').includes(q))).sort((a,b)=>Number(linked.has(b.id))-Number(linked.has(a.id))||a.name.localeCompare(b.name,'fr'));
for(const c of matches){const row=N('article','admin-contact-entry'),name=N('strong','',c.name);row.append(name);if(!linked.has(c.id)){row.append(B('Associer',()=>save('/contact-link',{admin_id:owner.id,contact_id:c.id})));list.append(row);continue}
if(c.phone){if(config.mobile)row.append(external(c.phone,'tel:'+c.phone.replace(/[^+0-9]/g,'')));else row.append(B(c.phone,async e=>{const target=e.currentTarget;try{await navigator.clipboard.writeText(c.phone);target.textContent='Numéro copié'}catch{status.textContent='Copie indisponible : '+c.phone}}))}if(c.email)row.append(external(c.email,'mailto:'+c.email));if(c.address)row.append(external(c.address,'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(c.address)));if(c.doctolib)row.append(external('Doctolib',c.doctolib));if(c.website)row.append(external('Site internet',c.website));if(c.notes)row.append(N('p','',c.notes));const options=N('details'),title=N('summary','','Options');options.append(title,B('Modifier',()=>editor(c)),B('Retirer de cette démarche',()=>save('/contact-link',{admin_id:owner.id,contact_id:c.id,unlink:true})));row.append(options);list.append(row)}if(!matches.length)list.append(N('p','muted','Aucun contact.'))}search.oninput=draw;draw();search.focus();}};
})();
